#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashSet;

    #[test]
    fn table_is_well_formed() {
        let mut seen = HashSet::new();
        for (fr, en, es) in TABLE {
            assert!(!fr.is_empty() && !en.is_empty() && !es.is_empty(), "empty entry: {fr}");
            assert!(seen.insert(*fr), "duplicate key: {fr}");
        }
    }

    /// Every `tr("…")` literal (and the string constants fed to `tr`) must have a translation.
    #[test]
    fn every_ui_string_is_translated() {
        let sources = [
            include_str!("errcode.rs"),
            include_str!("main.rs"),
            include_str!("portable.rs"),
            include_str!("session.rs"),
            include_str!("ui_auth.rs"),
            include_str!("ui_common.rs"),
            include_str!("ui_health.rs"),
            include_str!("ui_passkey.rs"),
            include_str!("ui_settings.rs"),
            include_str!("ui_setup.rs"),
            include_str!("ui_vault.rs"),
        ];
        let keys: HashSet<&str> = TABLE.iter().map(|t| t.0).collect();
        let mut missing = Vec::new();
        for src in sources {
            let mut rest = src;
            while let Some(i) = rest.find("tr(\"") {
                let after = &rest[i + 4..];
                if let Some(j) = after.find("\")") {
                    let lit = after[..j].replace("\\\\", "\\");
                    if !keys.contains(lit.as_str()) {
                        missing.push(lit);
                    }
                    rest = &after[j..];
                } else {
                    break;
                }
            }
        }
        // strings reaching `tr` through constants / library errors
        for lit in [
            "30 secondes", "1 minute", "2 minutes", "5 minutes", "10 minutes", "30 minutes", "1 heure",
            "Standard — 64 Mo, 3 passes", "Élevé — 256 Mo, 4 passes", "Maximum — 512 Mo, 5 passes",
            "Fichier CSV illisible.",
            "Colonnes non reconnues : il faut au moins un nom/site et un mot de passe.",
            "Aucune entrée exploitable dans ce fichier.",
        ] {
            if !keys.contains(lit) {
                missing.push(lit.to_owned());
            }
        }
        missing.sort();
        missing.dedup();
        assert!(missing.is_empty(), "untranslated strings: {missing:#?}");
    }
}
